title: Format euros with the German locale
description:
Euro amounts were formatted the US way (€1,234.56). Use de-DE for EUR and en-GB for GBP.

--- src/money.js (modified, +3 −1)
@@ -4,6 +4,8 @@ export function toCents(amount) {
   return Math.round(amount * 100);
 }

+const LOCALE = { USD: "en-US", EUR: "de-DE", GBP: "en-GB" };
+
 export function formatCents(cents, currency = "USD") {
-  return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(cents / 100);
+  return new Intl.NumberFormat(LOCALE[currency] ?? "en-US", { style: "currency", currency }).format(cents / 100);
 }

